#include "display.h"

// MD KIT: generated by tools/make_engine.py. The screen: the selected key's
// machine as the design draws one machine (art.h): its instrument on the left,
// its family's panel on the right, at that key's values (a held step's locks
// included), struck by each note.
namespace mdkit {
// A whole number and its unit, as stock shows a key's pan ("-40", "0", "40")
// and level ("-6dB", "0dB"): no plus sign.
inline void signed_text(char* out, u32 capacity, i32 value, const char* unit) {
    char text[12];
    u32 n = 0;
    if (value < 0) { text[n++] = '-'; value = -value; }
    if (value > 999) value = 999;
    if (value >= 100) text[n++] = static_cast<char>('0' + value / 100);
    if (value >= 10) text[n++] = static_cast<char>('0' + value / 10 % 10);
    text[n++] = static_cast<char>('0' + value % 10);
    for (u32 i = 0; unit[i] && n + 1 < sizeof(text); ++i) text[n++] = unit[i];
    text[n] = 0;
    opxy::draw::copy(out, capacity, text);
}

inline void display_reset(DisplayState& state) {
    state.hit.initialized = 0;
    state.hit.age = 1 << 20;
    state.header.reset();
    state.shown = 0;
}

inline void display(DisplayState& state, const opxy::draw::Input& input, Frame& frame) {
    const u32 selected = input.model < kit::models ? input.model : 0;
    // A view keeps a path whose key is unchanged, and the key comes from its
    // values: another machine's outline can carry the same key. A new machine
    // starts its paths afresh (begin shapes each again).
    if (state.shown != selected + 1) {
        state.shown = selected + 1;
        for (u32 p = 0; p < Frame::path_count; ++p) frame.paths[p].key = 0;
    }
    md::view::begin(frame, input);
    state.hit.update(input);
    const md::view::Moment moment = {state.hit.age, input.reduced_motion, state.hit.quiet};
    i32 own[8];
    kit::controls(selected, input.slots, own);
    for (u32 m = 0; m < kit::models; ++m)
        if (m != selected) md::rig::hide_all(frame, art::members, art::machines[m]);
    md::rig::draw(frame, art::parts, art::effects, art::members, art::machines[selected], own, moment,
                  selected == 9 || selected == 25 ? md::rig::shaker : md::rig::drum);
    switch (selected) {
    case 0: md::trx_bd::view(frame, own, moment); break;
    case 1: md::trx_sd::view(frame, own, moment); break;
    case 2: md::trx_xt::view(frame, own, moment); break;
    case 3: md::trx_cp::view(frame, own, moment); break;
    case 4: md::trx_rs::view(frame, own, moment); break;
    case 5: md::trx_cb::view(frame, own, moment); break;
    case 6: md::trx_ch::view(frame, own, moment); break;
    case 7: md::trx_oh::view(frame, own, moment); break;
    case 8: md::trx_cy::view(frame, own, moment); break;
    case 9: md::trx_ma::view(frame, own, moment); break;
    case 10: md::trx_cl::view(frame, own, moment); break;
    case 11: md::trx_xc::view(frame, own, moment); break;
    case 12: md::trx_b2::view(frame, own, moment); break;
    case 13: md::efm_bd::view(frame, own, moment); break;
    case 14: md::efm_sd::view(frame, own, moment); break;
    case 15: md::efm_xt::view(frame, own, moment); break;
    case 16: md::efm_cp::view(frame, own, moment); break;
    case 17: md::efm_rs::view(frame, own, moment); break;
    case 18: md::efm_cb::view(frame, own, moment); break;
    case 19: md::efm_hh::view(frame, own, moment); break;
    case 20: md::efm_cy::view(frame, own, moment); break;
    case 21: md::pi_bd::view(frame, own, moment); break;
    case 22: md::pi_sd::view(frame, own, moment); break;
    case 23: md::pi_mt::view(frame, own, moment); break;
    case 24: md::pi_ml::view(frame, own, moment); break;
    case 25: md::pi_ma::view(frame, own, moment); break;
    case 26: md::pi_rs::view(frame, own, moment); break;
    case 27: md::pi_rc::view(frame, own, moment); break;
    case 28: md::pi_cc::view(frame, own, moment); break;
    case 29: md::pi_hh::view(frame, own, moment); break;
    case 30: md::gnd_sn::view(frame, own, moment); break;
    case 31: md::gnd_ns::view(frame, own, moment); break;
    case 32: md::gnd_im::view(frame, own, moment); break;
    default: break;
    }
    // The header last: both rows, the one the encoders edit on its bar, as the
    // Monomachine engines show their two pages. A slot the machine lacks is
    // blank on either row. While Shift is held both rows name Shift's controls
    // and their choices instead, stacked as the pages are: the first row's
    // (MACHINE, CHOKE, PAN, LEVEL) on top, the second's (FILTER, SRR, FX I,
    // FX II) under it, the one the encoders edit bright on the bar. Shift swaps
    // all eight names and values at once.
    static const char* const chokes[4] = {"none", "1", "2", "3"};
    const char* titles[8];
    char values[8][opxy::draw::header_capacity];
    for (u32 i = 0; i < 8; ++i) {
        titles[i] = kit::model[selected].labels[i];
        if (titles[i][0]) md::view::value127(values[i], opxy::draw::header_capacity, input.slots[i]);
        else opxy::draw::copy(values[i], opxy::draw::header_capacity, " ");   // the stock header's blank
    }
    if (input.shift) {
        // The key's own pan, -100..100 with 0 centred, and level in dB; and
        // its sends: 0 follows the track's (TRK), 1..7 send its own 0..100 percent.
        char pan[8], level[8], sends[2][4];
        signed_text(pan, sizeof(pan), input.pan, "");
        signed_text(level, sizeof(level), input.level, "dB");
        for (u32 s = 0; s < 2; ++s) {
            // SDK 1.15: 0 follows the track's send (TRK), else the key's percent + 1.
            const i32 percent = input.pad[2 + s] - 1;
            if (percent >= 0) signed_text(sends[s], sizeof(sends[s]), percent > 100 ? 100 : percent, "");
            else opxy::draw::copy(sends[s], sizeof(sends[s]), "TRK");
        }
        static const char* const shift_titles[2][4] = {{"MACHINE", "CHOKE", "PAN", "LEVEL"}, {"FILTER", "SRR", "FX I", "FX II"}};
        const char* const shift_values[2][4] = {{kit::model[selected].name, chokes[input.choices[2] & 3u], pan, level}, {kit::filter_text[md::clamp(input.pad[0], -16, 15) + 16], kit::srr_text[md::clamp(input.pad[1], 0, 15)], sends[0], sends[1]}};
        for (u32 line = 0; line < 2; ++line)
            for (u32 c = 0; c < 4; ++c) {
                titles[4 * line + c] = shift_titles[line][c];
                opxy::draw::copy(values[4 * line + c], opxy::draw::header_capacity, shift_values[line][c]);
            }
        titles[0] = kit::families[input.choices[0] < kit::family_count ? input.choices[0] : 0];
    }
    opxy::draw::page_header(state.header, input, frame, titles, values, header_node);
}
}
